UPDATE vendor_quote
SET status = 'SELECTED'
WHERE procurement_id = #{procurementId}
  AND quote_id = #{quoteId}
  AND status = 'SUBMITTED'

UPDATE vendor_quote
SET status = 'REJECTED'
WHERE procurement_id = #{procurementId}
  AND quote_id != #{quoteId}
  AND status IN ('REQUESTED', 'SUBMITTED')

