UPDATE procurement
SET status = 'CANCELLED'
WHERE procurement_id = #{procurementId}
  AND status IN ('REQUESTED', 'QUOTING')

    AND department_id = #{departmentId}

UPDATE procurement
SET status = 'QUOTING'
WHERE procurement_id = #{procurementId}
  AND status = 'REQUESTED'

    AND department_id = #{departmentId}

mapper.select:
SELECT department_id
FROM department
WHERE department_code = #{departmentCode}
